<script lang="ts">
	import { AlertTriangle, BarChart3, CalendarRange, CircleDollarSign, Zap } from '@lucide/svelte';
	import AppShell from '#lib/components/AppShell.svelte';
	import HorizontalBarChart from '#lib/components/HorizontalBarChart.svelte';
	import PageHeader from '#lib/components/PageHeader.svelte';
	import { formatDateTime, formatNaira, formatNumber } from '#lib/format.js';
	import type { PageProps } from './$types';
	let { data }: PageProps = $props();
	let usageItems = $derived(data.histories.map((history) => ({ key: history.meter.providerId, label: history.meter.name, count: history.summary.intervalUsageKwh ?? 0 })));
	let negativeAccounts = $derived((data.overview?.customers ?? []).filter((customer) => (customer.accountBalance ?? 0) < 0));
	let earliest = $derived(data.histories.map((history) => history.coverage.from).filter((value): value is string => Boolean(value)).sort()[0] ?? null);
	let latest = $derived(data.histories.map((history) => history.coverage.to).filter((value): value is string => Boolean(value)).sort().at(-1) ?? null);
</script>

<svelte:head><title>Reports & analytics | MicroAccess Smart Metering</title></svelte:head>
<AppShell active="reports">
	<PageHeader eyebrow="Management and energy intelligence" title="Reports & analytics" description="Dated provider readings interpreted as period usage, with explicit coverage and data-quality boundaries." refreshHref="/reports?refresh=true" />
	{#if data.error}<section class="state">{data.error.message}</section>{:else if data.overview}
		<section class="report-banner"><CalendarRange size={19} /><div><strong>Current provider reading window</strong><span>{formatDateTime(earliest)} – {formatDateTime(latest)}</span></div><p>This is a recent window, not a certified full-history archive.</p></section>
		<section class="kpis"><article><Zap size={18} /><span>Source / bulk meters</span><strong>{data.histories.length}</strong><p>With history requests attempted</p></article><article><BarChart3 size={18} /><span>Dated readings</span><strong>{data.histories.reduce((sum, item) => sum + item.coverage.readingCount, 0)}</strong><p>Across source and bulk meters</p></article><article><CircleDollarSign size={18} /><span>Negative customer balances</span><strong>{negativeAccounts.length}</strong><p>Monetary ledger condition—not energy usage</p></article></section>
		<section class="grid">
			<article class="panel chart"><div class="heading"><div><p>Energy inputs</p><h2>Usage in returned reading window</h2></div><span>kWh by source meter</span></div><HorizontalBarChart items={usageItems} accent="linear-gradient(90deg, var(--blue), var(--sky))" /></article>
			<aside class="panel methodology"><div class="heading"><div><p>Management interpretation</p><h2>Savings calculation status</h2></div></div><div class="gate"><AlertTriangle size={17} /><div><strong>Not yet certified</strong><p>A defensible savings figure needs verified grid and solar meter direction, a complete common time range, an approved tariff, and a baseline. The application will not call negative account balances “savings.”</p></div></div><ul><li>Grid consumption and solar contribution are shown separately.</li><li>Cumulative registers are never summed.</li><li>Period usage comes from dated interval usage or register differences.</li><li>Future savings reports will retain tariff version and calculation dates.</li></ul></aside>
		</section>
		<section class="panel source-table"><div class="heading"><div><p>Source analysis</p><h2>Meter-by-meter coverage</h2></div></div><div class="table-wrap"><table><thead><tr><th>Meter</th><th>Coverage</th><th>Readings</th><th>Period usage</th><th>Register change</th><th>Latest register</th></tr></thead><tbody>{#each data.histories as history (history.meter.providerId)}<tr><td><a href={`/meters/${history.meter.providerId}`}><strong>{history.meter.name}</strong><span>{history.meter.meterNumber}</span></a></td><td>{formatDateTime(history.coverage.from)}<span>to {formatDateTime(history.coverage.to)}</span></td><td>{history.coverage.readingCount}</td><td>{formatNumber(history.summary.intervalUsageKwh)} kWh</td><td>{formatNumber(history.summary.registerChangeKwh)} kWh</td><td>{formatNumber(history.summary.latestReadingKwh)} kWh</td></tr>{/each}</tbody></table></div></section>
		<section class="panel balances"><div class="heading"><div><p>Financial data quality</p><h2>Negative provider account balances</h2></div><span>{negativeAccounts.length} accounts</span></div><p class="explain">These are customer ledger balances after usage-charge postings. They do not describe a monthly meter total, and they are not evidence of savings.</p><div class="balance-list">{#each negativeAccounts.slice(0, 10) as customer (customer.providerId)}<a href={`/customers/${customer.providerId}`}><span><strong>{customer.displayName}</strong><small>{customer.assignedMeterNumber ?? 'No observed meter'}</small></span><strong>{formatNaira(customer.accountBalance)}</strong></a>{/each}</div></section>
	{/if}
</AppShell>

